import { PrismaClient } from "@prisma/client";

declare global {
  // eslint-disable-next-line no-var
  var prismaGlobal: PrismaClient | undefined;
}

// In dev, disconnect any stale client (handles DB file replacement after prisma db push)
if (process.env.NODE_ENV !== "production" && global.prismaGlobal) {
  global.prismaGlobal.$disconnect().catch(() => {});
  global.prismaGlobal = undefined;
}

const db = new PrismaClient();

if (process.env.NODE_ENV !== "production") {
  global.prismaGlobal = db;
}

export default db;

