  1→import db from "../db.server";
  2→
  3→function slugify(text: string): string {
  4→  return (
  5→    text
  6→      .toLowerCase()
  7→      .replace(/[^a-z0-9\s-]/g, "")
  8→      .replace(/\s+/g, "-")
  9→      .replace(/-+/g, "-")
 10→      .replace(/^-|-$/g, "") || "quiz"
 11→  );
 12→}
 13→
 14→async function generateUniqueSlug(
 15→  shop: string,
 16→  title: string,
 17→  excludeId?: string
 18→): Promise<string> {
 19→  const base = slugify(title);
 20→  let slug = base;
 21→  let counter = 0;
 22→  while (true) {
 23→    const existing = await db.quiz.findFirst({
 24→      where: {
 25→        shop,
 26→        slug,
 27→        ...(excludeId ? { NOT: { id: excludeId } } : {}),
 28→      },
 29→    });
 30→    if (!existing) break;
 31→    counter++;
 32→    slug = `${base}-${counter}`;
 33→  }
 34→  return slug;
 35→}
 36→
 37→export async function getQuizzes(shop: string) {
 38→  return db.quiz.findMany({
 39→    where: { shop, status: { not: "archived" } },
 40→    orderBy: { createdAt: "desc" },
 41→    include: {
 42→      _count: { select: { questions: true, responses: true } },
 43→    },
 44→  });
 45→}
 46→
 47→export async function getQuizById(id: string, shop: string) {
 48→  return db.quiz.findFirst({
 49→    where: { id, shop },
 50→    include: {
 51→      questions: {
 52→        include: { answers: { orderBy: { position: "asc" } } },
 53→        orderBy: { position: "asc" },
 54→      },
 55→      resultPages: { orderBy: { position: "asc" } },
 56→      _count: { select: { responses: true } },
 57→    },
 58→  });
 59→}
 60→
 61→export async function createQuiz(
 62→  shop: string,
 63→  data: { title: string; type?: string; description?: string }
 64→) {
 65→  const slug = await generateUniqueSlug(shop, data.title);
 66→  return db.quiz.create({
 67→    data: {
 68→      shop,
 69→      slug,
 70→      title: data.title,
 71→      type: data.type ?? "product-recommendation",
 72→      description: data.description,
 73→    },
 74→  });
 75→}
 76→
 77→export async function updateQuiz(
 78→  id: string,
 79→  shop: string,
 80→  data: {
 81→    title?: string;
 82→    description?: string | null;
 83→    status?: string;
 84→    settings?: string;
 85→    styling?: string;
