import db from "../db.server";

function slugify(text: string): string {
  return (
    text
      .toLowerCase()
      .replace(/[^a-z0-9\s-]/g, "")
      .replace(/\s+/g, "-")
      .replace(/-+/g, "-")
      .replace(/^-|-$/g, "") || "quiz"
  );
}

async function generateUniqueSlug(
  shop: string,
  title: string,
  excludeId?: string
): Promise<string> {
  const base = slugify(title);
  let slug = base;
  let counter = 0;
  while (true) {
    const existing = await db.quiz.findFirst({
      where: {
        shop,
        slug,
        ...(excludeId ? { NOT: { id: excludeId } } : {}),
      },
    });
    if (!existing) break;
    counter++;
    slug = `${base}-${counter}`;
  }
  return slug;
}

export async function getQuizzes(shop: string) {
  return db.quiz.findMany({
    where: { shop, status: { not: "archived" } },
    orderBy: { createdAt: "desc" },
    include: {
      _count: { select: { questions: true, responses: true } },
    },
  });
}

export async function getQuizById(id: string, shop: string) {
  return db.quiz.findFirst({
    where: { id, shop },
    include: {
      questions: {
        include: { answers: { orderBy: { position: "asc" } } },
        orderBy: { position: "asc" },
      },
      resultPages: { orderBy: { position: "asc" } },
      _count: { select: { responses: true } },
    },
  });
}

export async function createQuiz(
  shop: string,
  data: { title: string; type?: string; description?: string }
) {
  const slug = await generateUniqueSlug(shop, data.title);
  return db.quiz.create({
    data: {
      shop,
      slug,
      title: data.title,
      type: data.type ?? "product-recommendation",
      description: data.description,
    },
  });
}

export async function updateQuiz(
  id: string,
  shop: string,
  data: {
    title?: string;
    description?: string | null;
    status?: string;
    settings?: string;
    styling?: string;
  }
) {
  const quiz = await db.quiz.findFirst({ where: { id, shop } });
  if (!quiz) throw new Error("Quiz not found");
  return db.quiz.update({
    where: { id },
    data: {
      ...data,
      ...(data.status === "active" && quiz.status !== "active"
        ? { publishedAt: new Date() }
        : {}),
      updatedAt: new Date(),
    },
  });
}

export async function deleteQuiz(id: string, shop: string): Promise<void> {
  const quiz = await db.quiz.findFirst({ where: { id, shop } });
  if (!quiz) throw new Error("Quiz not found");
  await db.quiz.delete({ where: { id } });
}

export async function publishQuiz(id: string, shop: string) {
  const quiz = await db.quiz.findFirst({ where: { id, shop } });
  if (!quiz) throw new Error("Quiz not found");
  return db.quiz.update({
    where: { id },
    data: {
      status: "active",
      publishedAt: quiz.publishedAt ?? new Date(),
    },
  });
}

export async function duplicateQuiz(id: string, shop: string) {
  const quiz = await db.quiz.findFirst({
    where: { id, shop },
    include: {
      questions: {
        include: { answers: { orderBy: { position: "asc" } } },
        orderBy: { position: "asc" },
      },
      resultPages: { orderBy: { position: "asc" } },
    },
  });
  if (!quiz) throw new Error("Quiz not found");

  const newSlug = await generateUniqueSlug(shop, `${quiz.title} Copy`);

  return db.quiz.create({
    data: {
      shop,
      title: `${quiz.title} (Copy)`,
      slug: newSlug,
      type: quiz.type,
      description: quiz.description,
      settings: quiz.settings,
      styling: quiz.styling,
      questions: {
        create: quiz.questions.map((q: typeof quiz.questions[number]) => ({
          type: q.type,
          title: q.title,
          description: q.description,
          required: q.required,
          position: q.position,
          settings: q.settings,
          logic: q.logic,
          answers: {
            create: q.answers.map((a: typeof q.answers[number]) => ({
              text: a.text,
              position: a.position,
              score: a.score,
              productTags: a.productTags,
            })),
          },
        })),
      },
      resultPages: {
        create: quiz.resultPages.map((r: typeof quiz.resultPages[number]) => ({
          title: r.title,
          description: r.description,
          type: r.type,
          position: r.position,
          productLimit: r.productLimit,
          layout: r.layout,
        })),
      },
    },
  });
}

export async function getDashboardStats(shop: string) {
  const thirtyDaysAgo = new Date();
  thirtyDaysAgo.setDate(thirtyDaysAgo.getDate() - 30);
  const sixtyDaysAgo = new Date();
  sixtyDaysAgo.setDate(sixtyDaysAgo.getDate() - 60);

  const [quizzes, currentResponses, previousResponses] = await Promise.all([
    db.quiz.findMany({
      where: { shop, status: { not: "archived" } },
      select: {
        id: true,
        title: true,
        completions: true,
        status: true,
        createdAt: true,
      },
      orderBy: { completions: "desc" },
    }),
    db.quizResponse.findMany({
      where: {
        shop,
        createdAt: { gte: thirtyDaysAgo },
        completedAt: { not: null },
      },
      select: { revenue: true, email: true },
    }),
    db.quizResponse.findMany({
      where: {
        shop,
        createdAt: { gte: sixtyDaysAgo, lt: thirtyDaysAgo },
        completedAt: { not: null },
      },
      select: { revenue: true, email: true },
    }),
  ]);

  const currentRevenue = currentResponses.reduce((sum, r) => sum + r.revenue, 0);
  const previousRevenue = previousResponses.reduce(
    (sum, r) => sum + r.revenue,
    0
  );
  const currentCompletions = currentResponses.length;
  const previousCompletions = previousResponses.length;
  const currentEmails = currentResponses.filter((r) => r.email).length;
  const previousEmails = previousResponses.filter((r) => r.email).length;

  function trend(current: number, previous: number): string {
    if (previous === 0) return current > 0 ? "+100%" : "0%";
    const pct = ((current - previous) / previous) * 100;
    return `${pct >= 0 ? "+" : ""}${pct.toFixed(1)}%`;
  }

  return {
    revenue: {
      value: currentRevenue,
      formatted: `$${currentRevenue.toFixed(2)}`,
      trend: trend(currentRevenue, previousRevenue),
      up: currentRevenue >= previousRevenue,
    },
    completions: {
      value: currentCompletions,
      formatted: currentCompletions.toLocaleString(),
      trend: trend(currentCompletions, previousCompletions),
      up: currentCompletions >= previousCompletions,
    },
    emailsCaptured: {
      value: currentEmails,
      formatted: currentEmails.toLocaleString(),
      trend: trend(currentEmails, previousEmails),
      up: currentEmails >= previousEmails,
    },
    quizzes,
    activeQuizCount: quizzes.filter((q) => q.status === "active").length,
  };
}

