 47→export async function getQuizById(id: string, shop: string) {
 48→  return db.quiz.findFirst({
 49→    where: { id, shop },
 50→    include: {
 51→      questions: {
 52→        include: { answers: { orderBy: { position: "asc" } } },
 53→        orderBy: { position: "asc" },
 54→      },
 55→      resultPages: { orderBy: { position: "asc" } },
 56→      _count: { select: { responses: true } },
 57→    },
 58→  });
 59→}
