111→// ─── Plan limit helper (server-side only) ─────────────────────────────────────
112→
113→async function checkPlanLimit(shop: string): Promise<string | null> {
114→  const count = await db.quiz.count({
115→    where: { shop, status: { not: "archived" } },
116→  });
117→  const sub = await db.subscription.findUnique({
118→    where: { shop },
119→    select: { planId: true },
120→  });
121→  const planId = (sub?.planId ?? "free") as PlanId;
122→  const limit = PLAN_LIMITS[planId]?.quizLimit ?? 1;
123→  if (count >= limit) {
124→    return `You've reached the ${limit}-quiz limit for your ${planId} plan. Upgrade to create more.`;
125→  }
126→  return null;
127→}
