129→// ─── Loader ───────────────────────────────────────────────────────────────────
130→
131→export const loader = async ({ request }: LoaderFunctionArgs) => {
132→  const { session } = await authenticate.admin(request);
133→  try {
134→    const [quizzes, templates] = await Promise.all([
135→      getQuizzes(session.shop),
136→      Promise.resolve(getTemplatesMeta()),
137→    ]);
138→    return { quizzes, templates };
139→  } catch {
140→    return { quizzes: [], templates: getTemplatesMeta() };
141→  }
142→};
