144→// ─── Action ───────────────────────────────────────────────────────────────────
145→
146→export const action = async ({
147→  request,
148→}: ActionFunctionArgs): Promise<ActionResult | UNSAFE_DataWithResponseInit<ActionResult>> => {
149→  const { session } = await authenticate.admin(request);
150→  const formData = await request.formData();
151→  const intent = formData.get("intent") as string;
152→
153→  try {
154→    // ── Create from template ─────────────────────────────────────────────────
155→    if (intent === "create-from-template") {
156→      const templateId = formData.get("templateId") as string;
157→      if (!templateId) {
158→        return data<ActionResult>(
159→          { error: "Template ID is required" },
160→          { status: 400 },
161→        );
162→      }
163→      const limitError = await checkPlanLimit(session.shop);
164→      if (limitError) {
165→        return data<ActionResult>({ error: limitError }, { status: 403 });
166→      }
167→      const quizId = await createQuizFromTemplate(session.shop, templateId);
168→      return { success: true, quizId, message: "Quiz created from template!" };
169→    }
170→
171→    // ── Create blank ─────────────────────────────────────────────────────────
172→    if (intent === "create-blank") {
173→      const limitError = await checkPlanLimit(session.shop);
174→      if (limitError) {
175→        return data<ActionResult>({ error: limitError }, { status: 403 });
176→      }
177→      const quizId = await createBlankQuiz(session.shop);
178→      return { success: true, quizId, message: "Quiz created!" };
179→    }
180→
181→    // ── Archive ───────────────────────────────────────────────────────────────
182→    if (intent === "archive") {
183→      const id = formData.get("id") as string;
184→      const quiz = await db.quiz.findFirst({
185→        where: { id, shop: session.shop },
186→      });
187→      if (!quiz) {
188→        return data<ActionResult>(
189→          { error: "Quiz not found or access denied" },
190→          { status: 404 },
191→        );
192→      }
193→      await db.quiz.update({
194→        where: { id },
195→        data: { status: "archived" },
196→      });
197→      return { success: true, message: "Quiz archived" };
198→    }
199→
200→    // ── Delete ────────────────────────────────────────────────────────────────
201→    if (intent === "delete") {
202→      const id = formData.get("id") as string;
203→      await deleteQuiz(id, session.shop);
204→      return { success: true, message: "Quiz deleted" };
205→    }
206→
207→    return data<ActionResult>({ error: "Unknown intent" }, { status: 400 });
208→  } catch (error) {
209→    const message =
210→      error instanceof Error ? error.message : "Action failed";
211→    return data<ActionResult>({ error: message }, { status: 500 });
212→  }
213→};
