306→// ─── AIGenerationOverlay ──────────────────────────────────────────────────────
307→
308→function AIGenerationOverlay({ onAnimationDone }: { onAnimationDone: () => void }) {
309→  const [currentStep, setCurrentStep] = useState(0);
310→  const [completedSteps, setCompletedSteps] = useState<number[]>([]);
311→
312→  useEffect(() => {
313→    const timers: ReturnType<typeof setTimeout>[] = [];
314→
315→    progressSteps.forEach((_, index) => {
316→      const advanceTimer = setTimeout(() => {
317→        setCurrentStep(index);
318→        if (index > 0) {
319→          setCompletedSteps((prev) =>
320→            prev.includes(index - 1) ? prev : [...prev, index - 1],
321→          );
322→        }
323→      }, index * 750);
324→      timers.push(advanceTimer);
325→    });
326→
327→    // Mark the last step complete
328→    const lastCompleteTimer = setTimeout(() => {
329→      setCompletedSteps((prev) =>
330→        prev.includes(progressSteps.length - 1)
331→          ? prev
332→          : [...prev, progressSteps.length - 1],
333→      );
334→    }, progressSteps.length * 750);
335→    timers.push(lastCompleteTimer);
336→
337→    // Signal animation is done with a small buffer
338→    const doneTimer = setTimeout(() => {
339→      onAnimationDone();
340→    }, progressSteps.length * 750 + 500);
341→    timers.push(doneTimer);
342→
343→    return () => timers.forEach(clearTimeout);
344→    // onAnimationDone is stable (wrapped in useCallback at the call site)
345→    // eslint-disable-next-line react-hooks/exhaustive-deps
346→  }, []);
347→
348→  return (
349→    <div
350→      style={{
351→        position: "fixed",
352→        inset: 0,
353→        zIndex: 9999,
354→        background: "rgba(255, 255, 255, 0.97)",
355→        display: "flex",
356→        alignItems: "center",
357→        justifyContent: "center",
358→      }}
359→    >
360→      <div style={{ textAlign: "center", maxWidth: 420 }}>
361→        {/* Spinner */}
362→        <div
363→          style={{
364→            width: 64,
365→            height: 64,
366→            margin: "0 auto 24px",
367→            border: "4px solid var(--p-color-border)",
368→            borderTopColor: "var(--p-color-border-emphasis)",
369→            borderRadius: "50%",
370→            animation: "quizsnap-spin 0.8s linear infinite",
371→          }}
372→        />
373→        <style>{`@keyframes quizsnap-spin { to { transform: rotate(360deg); } }`}</style>
374→
375→        <BlockStack gap="200">
376→          <Text as="p" variant="headingLg" fontWeight="bold">
377→            Building your quiz with AI...
378→          </Text>
379→          <Text as="p" variant="bodySm" tone="subdued">
380→            This usually takes a few seconds
381→          </Text>
382→        </BlockStack>
383→
384→        <div style={{ marginTop: 32, textAlign: "left" }}>
385→          <BlockStack gap="300">
386→            {progressSteps.map((step, index) => {
387→              const isCompleted = completedSteps.includes(index);
388→              const isCurrent = currentStep === index && !isCompleted;
389→              return (
390→                <InlineStack key={index} gap="300" blockAlign="center">
391→                  <div
392→                    style={{
393→                      width: 24,
394→                      height: 24,
395→                      borderRadius: "50%",
396→                      display: "flex",
397→                      alignItems: "center",
398→                      justifyContent: "center",
399→                      fontSize: 14,
400→                      flexShrink: 0,
401→                      background: isCompleted
402→                        ? "var(--p-color-bg-fill-success)"
403→                        : isCurrent
404→                          ? "var(--p-color-bg-fill-emphasis)"
405→                          : "var(--p-color-bg-surface-secondary)",
406→                      color:
407→                        isCompleted || isCurrent
408→                          ? "#fff"
409→                          : "var(--p-color-text-subdued)",
410→                    }}
411→                  >
412→                    {isCompleted ? "\u2713" : index + 1}
413→                  </div>
414→                  <Text
415→                    as="p"
416→                    variant="bodyMd"
417→                    tone={
418→                      isCompleted
419→                        ? "success"
420→                        : isCurrent
421→                          ? undefined
422→                          : "subdued"
423→                    }
424→                    fontWeight={isCurrent ? "semibold" : "regular"}
425→                  >
426→                    {step}
427→                  </Text>
428→                </InlineStack>
429→              );
430→            })}
431→          </BlockStack>
432→        </div>
433→      </div>
434→    </div>
435→  );
436→}
