 81→    .join(" ");
 82→}
 83→
 84→// ─── Template emoji mapping ───────────────────────────────────────────────────
 85→
 86→const TEMPLATE_EMOJI: Record<string, string> = {
 87→  skincare: "\uD83E\uDDF4",
 88→  supplement: "\uD83D\uDC8A",
 89→  style: "\uD83D\uDC57",
