  1→/**
  2→ * Manual validation helpers — no external validation library required.
  3→ * These functions return `null` on success or an error message string on failure.
  4→ * For form actions: run all validators and collect errors before returning to the client.
  5→ */
  6→
  7→// ── Types ─────────────────────────────────────────────────────────────────────
  8→
  9→export interface ValidationError {
 10→  field: string;
 11→  message: string;
 12→}
 13→
 14→export interface ValidationResult {
 15→  valid: boolean;
 16→  errors: ValidationError[];
 17→}
 18→
 19→// ── Helpers ───────────────────────────────────────────────────────────────────
 20→
 21→function err(field: string, message: string): ValidationError {
 22→  return { field, message };
 23→}
 24→
 25→// ── Quiz validators ───────────────────────────────────────────────────────────
 26→
 27→const QUIZ_TYPES = [
 28→  "product-recommendation",
 29→  "personality",
 30→  "assessment",
 31→  "survey",
 32→  "lead-gen",
 33→] as const;
 34→
 35→const QUIZ_STATUSES = ["draft", "active", "paused", "archived"] as const;
 36→
 37→export interface QuizCreateInput {
 38→  title: string;
 39→  type?: string;
 40→  description?: string;
 41→}
 42→
 43→export function validateQuizCreate(input: QuizCreateInput): ValidationResult {
 44→  const errors: ValidationError[] = [];
 45→
 46→  if (!input.title || input.title.trim().length === 0) {
 47→    errors.push(err("title", "Title is required"));
 48→  } else if (input.title.trim().length > 255) {
 49→    errors.push(err("title", "Title must be 255 characters or fewer"));
 50→  }
 51→
 52→  if (input.type && !(QUIZ_TYPES as readonly string[]).includes(input.type)) {
 53→    errors.push(err("type", `Type must be one of: ${QUIZ_TYPES.join(", ")}`));
 54→  }
 55→
 56→  if (input.description && input.description.length > 1000) {
 57→    errors.push(err("description", "Description must be 1000 characters or fewer"));
 58→  }
 59→
 60→  return { valid: errors.length === 0, errors };
 61→}
 62→
 63→export interface QuizUpdateInput {
 64→  title?: string;
 65→  description?: string;
 66→  status?: string;
 67→  settings?: string;
 68→  styling?: string;
 69→}
 70→
 71→export function validateQuizUpdate(input: QuizUpdateInput): ValidationResult {
 72→  const errors: ValidationError[] = [];
 73→
 74→  if (input.title !== undefined) {
 75→    if (input.title.trim().length === 0) {
 76→      errors.push(err("title", "Title cannot be empty"));
 77→    } else if (input.title.trim().length > 255) {
 78→      errors.push(err("title", "Title must be 255 characters or fewer"));
 79→    }
 80→  }
 81→
 82→  if (input.description !== undefined && input.description.length > 1000) {
 83→    errors.push(err("description", "Description must be 1000 characters or fewer"));
 84→  }
 85→
 86→  if (input.status !== undefined && !(QUIZ_STATUSES as readonly string[]).includes(input.status)) {
 87→    errors.push(err("status", `Status must be one of: ${QUIZ_STATUSES.join(", ")}`));
 88→  }
 89→
 90→  if (input.settings !== undefined) {
 91→    try {
 92→      JSON.parse(input.settings);
 93→    } catch {
 94→      errors.push(err("settings", "Settings must be valid JSON"));
 95→    }
 96→  }
 97→
 98→  if (input.styling !== undefined) {
 99→    try {
100→      JSON.parse(input.styling);
101→    } catch {
102→      errors.push(err("styling", "Styling must be valid JSON"));
103→    }
104→  }
105→
106→  return { valid: errors.length === 0, errors };
107→}
