109→// ── Question validators ───────────────────────────────────────────────────────
110→
111→const QUESTION_TYPES = [
112→  "multiple-choice",
113→  "multiple-choice-multi",
114→  "image-choice",
115→  "slider",
116→  "text-input",
117→  "email",
118→  "date",
119→  "dropdown",
120→  "rating",
121→] as const;
122→
123→export interface QuestionCreateInput {
124→  quizId: string;
125→  type: string;
126→  title: string;
127→  description?: string;
128→  required?: boolean;
129→}
130→
131→export function validateQuestionCreate(input: QuestionCreateInput): ValidationResult {
132→  const errors: ValidationError[] = [];
133→
134→  if (!input.quizId || input.quizId.trim().length === 0) {
135→    errors.push(err("quizId", "Quiz ID is required"));
136→  }
137→
138→  if (!(QUESTION_TYPES as readonly string[]).includes(input.type)) {
139→    errors.push(err("type", `Type must be one of: ${QUESTION_TYPES.join(", ")}`));
140→  }
141→
142→  if (!input.title || input.title.trim().length === 0) {
143→    errors.push(err("title", "Question title is required"));
144→  } else if (input.title.trim().length > 500) {
145→    errors.push(err("title", "Title must be 500 characters or fewer"));
146→  }
147→
148→  if (input.description && input.description.length > 1000) {
149→    errors.push(err("description", "Description must be 1000 characters or fewer"));
150→  }
151→
152→  return { valid: errors.length === 0, errors };
153→}
