 90→// --- Helpers ---
 91→
 92→const questionTypeOptions = [
 93→  { label: "Single choice", value: "single" },
 94→  { label: "Multiple choice", value: "multiple" },
 95→  { label: "Image choice", value: "image-choice" },
 96→  { label: "Dropdown", value: "dropdown" },
 97→  { label: "Slider", value: "slider" },
