function SettingsTab({
  quiz,
  quizTitle,
  quizDescription,
  quizSlug,
  quizType,
  settings,
  onUpdateTitle: onUpdateTitleProp,
  onUpdateDescription: onUpdateDescProp,
  onUpdateSlug,
  onUpdateType,
  onUpdateSettings,
}: {
  quiz: LoaderQuiz;
  quizTitle: string;
  quizDescription: string;
  quizSlug: string;
  quizType: string;
  settings: QuizSettings;
  onUpdateTitle: (v: string) => void;
  onUpdateDescription: (v: string) => void;
  onUpdateSlug: (v: string) => void;
  onUpdateType: (v: string) => void;
  onUpdateSettings: (s: QuizSettings) => void;
}) {
  const embedCode = `<div id="quizsnap-${quizSlug}"></div>\n<script src="https://cdn.quizsnap.app/widget.js" data-quiz="${quizSlug}"></script>`;

  const handleCopyEmbed = useCallback(() => {
    if (typeof navigator !== "undefined") {
      navigator.clipboard
        .writeText(embedCode)
        .then(() => showToast("Embed code copied!"))
        .catch(() => showToast("Could not copy to clipboard", { isError: true }));
    }
  }, [embedCode]);

  return (
    <BlockStack gap="400">
      {/* Quiz Information */}
      <Card>
        <BlockStack gap="400">
          <Text as="h3" variant="headingSm" fontWeight="semibold">
            Quiz information
          </Text>
          <Divider />
          <FormLayout>
            <TextField
              label="Quiz title"
              value={quizTitle}
              onChange={onUpdateTitleProp}
              autoComplete="off"
              helpText="The display name of this quiz in the admin."
            />
            <TextField
              label="Description"
              value={quizDescription}
              onChange={onUpdateDescProp}
              autoComplete="off"
              multiline={3}
              helpText="Internal description. Not shown to shoppers."
            />
            <TextField
              label="URL slug"
              value={quizSlug}
              onChange={onUpdateSlug}
              autoComplete="off"
              prefix="/quiz/"
              helpText="Used in the storefront URL. Lowercase letters, numbers, and hyphens only."
            />
            <Select
              label="Quiz type"
              options={QUIZ_TYPE_OPTIONS}
              value={quizType}
              onChange={onUpdateType}
              helpText="Determines the result scoring and recommendation strategy."
            />
          </FormLayout>
        </BlockStack>
      </Card>

      {/* Email Capture */}
      <Card>
        <BlockStack gap="400">
          <Text as="h3" variant="headingSm" fontWeight="semibold">
            Email capture
          </Text>
          <Divider />
          <FormLayout>
            <Checkbox
              label="Require email before showing results"
              helpText="Shoppers must provide their email to see product recommendations."
              checked={settings.requireEmail}
              onChange={(v) =>
                onUpdateSettings({ ...settings, requireEmail: v })
              }
            />
            {settings.requireEmail && (
              <TextField
                label="Consent text"
                value={settings.emailConsentText}
                onChange={(v) =>
                  onUpdateSettings({ ...settings, emailConsentText: v })
                }
                autoComplete="off"
                multiline={2}
                helpText="Shown alongside the email capture field."
              />
            )}
          </FormLayout>
        </BlockStack>
      </Card>

      {/* Embed code */}
      <Card>
        <BlockStack gap="400">
          <InlineStack align="space-between" blockAlign="center">
            <InlineStack gap="200" blockAlign="center">
              <CodeIcon
                aria-label="Embed"
                style={{
                  width: 18,
                  height: 18,
                  color: "var(--p-color-icon-subdued)",
                }}
              />
              <Text as="h3" variant="headingSm" fontWeight="semibold">
                Embed and sharing
              </Text>
            </InlineStack>
            <Button
              icon={ClipboardIcon}
              size="slim"
              onClick={handleCopyEmbed}
            >
              Copy code
            </Button>
          </InlineStack>
          <Divider />
          <TextField
            label="Embed code"
            labelHidden
            value={embedCode}
            onChange={() => {}}
            autoComplete="off"
            multiline={3}
            readOnly
            helpText="Add this snippet to your storefront theme to display the quiz inline."
          />
          <Banner tone="info">
            <Text as="p" variant="bodySm">
              For popup and slide-in placement, configure the widget position in
              the Widget settings page.
            </Text>
          </Banner>
        </BlockStack>
      </Card>
    </BlockStack>
  );
}

// =============================================================================
// TAB 5: LOGIC
// =============================================================================

function LogicTab({
  questions,
  onUpdateLogic,
}: {
  questions: Question[];
  onUpdateLogic: (questionId: string, logic: QuestionLogic) => void;
}) {
  const questionsWithAnswers = questions.filter((q) => typeHasAnswers(q.type));

  if (questionsWithAnswers.length === 0) {
    return (
      <BlockStack gap="400">
        <Banner tone="info">
          <Text as="p" variant="bodyMd">
            Set up conditional logic to create personalized quiz paths. Questions
            without rules follow the default sequential order.
          </Text>
        </Banner>
        <EmptyState
          heading="No questions with branching options"
          image="https://cdn.shopify.com/s/files/1/0262/4071/2726/files/emptystate-files.png"
        >
          <Text as="p" variant="bodyMd" tone="subdued">
            Logic rules are only available for questions with answer options
            (Single choice, Image choice, Dropdown). Add those question types
            first.
          </Text>
        </EmptyState>
      </BlockStack>
    );
  }

  // Build "go to" options: all questions + "Results page"
  const gotoOptions = [
    { label: "Results page", value: "results" },
    ...questions.map((q, idx) => ({
      label: `Q${idx + 1}: ${q.title || "Untitled question"}`,
      value: q.id,
    })),
  ];

  return (
    <BlockStack gap="400">
      <Banner tone="info">
        <Text as="p" variant="bodyMd">
          Set up conditional logic to create personalized quiz paths. Questions
          without rules follow the default sequential order.
        </Text>
      </Banner>

      {questionsWithAnswers.map((question) => {
        const qIndex = questions.findIndex((q) => q.id === question.id);

        const handleAddRule = () => {
          const firstAnswerId = question.answers[0]?.id ?? "";
          const newRules = [
            ...question.logic.rules,
            { answerId: firstAnswerId, goto: "results" },
          ];
          onUpdateLogic(question.id, { rules: newRules });
        };

        const handleDeleteRule = (ruleIndex: number) => {
          const newRules = question.logic.rules.filter(
            (_, i) => i !== ruleIndex,
          );
          onUpdateLogic(question.id, { rules: newRules });
        };

        const handleUpdateRule = (
          ruleIndex: number,
          field: keyof LogicRule,
          value: string,
        ) => {
          const newRules = question.logic.rules.map((r, i) =>
            i === ruleIndex ? { ...r, [field]: value } : r,
          );
          onUpdateLogic(question.id, { rules: newRules });
        };

        return (
          <Card key={question.id}>
            <BlockStack gap="300">
              <InlineStack align="space-between" blockAlign="center">
                <InlineStack gap="200" blockAlign="center">
                  <Badge tone="info">{qIndex + 1}</Badge>
                  <Text as="h3" variant="headingSm" fontWeight="semibold">
                    {question.title || "Untitled question"}
                  </Text>
                  <Badge>{getTypeLabel(question.type)}</Badge>
                </InlineStack>
                <Button size="slim" icon={PlusIcon} onClick={handleAddRule}>
                  Add rule
                </Button>
              </InlineStack>

              {question.logic.rules.length === 0 ? (
                <Box
                  background="bg-surface-secondary"
                  borderRadius="200"
                  padding="300"
                >
                  <Text as="p" variant="bodySm" tone="subdued">
                    No branching rules. Quiz will follow sequential order after
                    this question.
                  </Text>
                </Box>
              ) : (
                <BlockStack gap="200">
                  {question.logic.rules.map((rule, ruleIndex) => {
                    const answerOptions = question.answers.map((a) => ({
                      label: a.text || `Option ${a.position + 1}`,
                      value: a.id,
                    }));

                    return (
                      <Box
                        key={ruleIndex}
                        background="bg-surface-secondary"
                        borderRadius="200"
                        padding="300"
                        borderWidth="025"
                        borderColor="border"
                      >
                        <InlineStack
                          gap="200"
                          blockAlign="center"
                          wrap={false}
                        >
                          <Text
                            as="span"
                            variant="bodySm"
                            tone="subdued"
                          >
                            If answer is
                          </Text>
                          <Box style={{ flex: 1 }}>
                            <Select
                              label="Answer"
                              labelHidden
                              options={answerOptions}
                              value={rule.answerId}
                              onChange={(v) =>
                                handleUpdateRule(ruleIndex, "answerId", v)
                              }
                            />
                          </Box>
                          <Text
                            as="span"
                            variant="bodySm"
                            tone="subdued"
                          >
                            go to
                          </Text>
                          <Box style={{ flex: 1 }}>
                            <Select
                              label="Go to"
                              labelHidden
                              options={gotoOptions}
                              value={rule.goto}
                              onChange={(v) =>
                                handleUpdateRule(ruleIndex, "goto", v)
                              }
                            />
                          </Box>
                          <Button
                            icon={XIcon}
                            tone="critical"
                            variant="plain"
                            onClick={() => handleDeleteRule(ruleIndex)}
                            accessibilityLabel="Delete rule"
                          />
                        </InlineStack>
                      </Box>
                    );
                  })}
                </BlockStack>
              )}
            </BlockStack>
          </Card>
        );
      })}
    </BlockStack>
  );
}

// =============================================================================
// MAIN PAGE COMPONENT
// =============================================================================

export default function QuizBuilder() {
  const loaderData = useLoaderData<typeof loader>();
  const actionData = useActionData<typeof action>();
  const navigate = useNavigate();
  const submit = useSubmit();

  const {
    quiz,
    questions: initialQuestions,
    designSettings: initialDesign,
    quizSettings: initialSettings,
  } = loaderData;

  // Local state for each tab
  const [questions, setQuestions] = useState<Question[]>(initialQuestions);
  const [selectedQuestionIndex, setSelectedQuestionIndex] = useState(0);
  const [design, setDesign] = useState<DesignSettings>(initialDesign);
  const [quizTitle, setQuizTitle] = useState(quiz.title);
  const [quizDescription, setQuizDescription] = useState(quiz.description);
  const [quizSlug, setQuizSlug] = useState(quiz.slug);
  const [quizType, setQuizType] = useState(quiz.type);
  const [settings, setSettings] = useState<QuizSettings>(initialSettings);
  const [selectedTab, setSelectedTab] = useState(0);
  const [deleteModalOpen, setDeleteModalOpen] = useState(false);

  // Show toast on every action result
  useEffect(() => {
    if (!actionData) return;
    if (
      "success" in actionData &&
      actionData.success &&
      "message" in actionData
    ) {
      showToast(String(actionData.message), { duration: 3000 });
    } else if ("error" in actionData && actionData.error) {
      showToast(String(actionData.error), { duration: 4000, isError: true });
    }
  }, [actionData]);

  const tabs = [
    { id: "questions", content: "Questions", panelID: "questions-panel" },
    {
      id: "mapping",
      content: "Product Mapping",
      panelID: "mapping-panel",
    },
    { id: "design", content: "Design", panelID: "design-panel" },
    { id: "settings", content: "Settings", panelID: "settings-panel" },
    { id: "logic", content: "Logic", panelID: "logic-panel" },
  ];

  // ── Save handlers ──────────────────────────────────────────────────────────

  const handleSaveQuestions = useCallback(() => {
    const formData = new FormData();
    formData.set("intent", "save-questions");
    formData.set(
      "questions",
      JSON.stringify(
        questions.map((q, qi) => ({
          id: q.id,
          title: q.title,
          description: q.description,
          imageUrl: q.imageUrl,
          type: q.type,
          required: q.required,
          position: qi,
          settings: q.settings,
          logic: q.logic,
          answers: q.answers.map((a, ai) => ({
            text: a.text,
            imageUrl: a.imageUrl,
            score: a.score,
            productTags: a.productTags,
            nextQuestionId: a.nextQuestionId,
            position: ai,
          })),
        })),
      ),
    );
    submit(formData, { method: "POST" });
  }, [questions, submit]);

  const handleSaveDesign = useCallback(() => {
    const stylingObj = {
      primaryColor: design.primaryColor,
      buttonTextColor: design.buttonTextColor,
      buttonText: design.buttonText,
      fontFamily: design.fontFamily,
      borderRadius: design.borderRadius,
      showProgressBar: design.showProgressBar,
      progressBarStyle: design.progressBarStyle,
      showQuestionCount: design.showQuestionCount,
      resultsHeading: design.resultsHeading,
    };
    const formData = new FormData();
    formData.set("intent", "save-design");
    formData.set("title", quizTitle);
    formData.set("description", quizDescription);
    formData.set("styling", JSON.stringify(stylingObj));
    submit(formData, { method: "POST" });
  }, [design, quizTitle, quizDescription, submit]);

  const handleSaveSettings = useCallback(() => {
    const settingsObj = {
      requireEmail: settings.requireEmail,
      emailConsentText: settings.emailConsentText,
      showProgressBar: settings.showProgressBar,
    };
    const formData = new FormData();
    formData.set("intent", "save-settings");
    formData.set("title", quizTitle);
    formData.set("description", quizDescription);
    formData.set("slug", quizSlug);
    formData.set("type", quizType);
    formData.set("settings", JSON.stringify(settingsObj));
    submit(formData, { method: "POST" });
  }, [settings, quizTitle, quizDescription, quizSlug, quizType, submit]);

  const handleSaveLogic = useCallback(() => {
    const logicMap: Record<string, QuestionLogic> = {};
    for (const q of questions) {
      logicMap[q.id] = q.logic;
    }
    const formData = new FormData();
    formData.set("intent", "save-logic");
    formData.set("logic", JSON.stringify(logicMap));
    submit(formData, { method: "POST" });
  }, [questions, submit]);

  const handleSave = useCallback(() => {
    switch (selectedTab) {
      case 0:
      case 1:
        handleSaveQuestions();
        break;
      case 2:
        handleSaveDesign();
        break;
      case 3:
        handleSaveSettings();
        break;
      case 4:
        handleSaveLogic();
        break;
      default:
        handleSaveQuestions();
    }
  }, [
    selectedTab,
    handleSaveQuestions,
    handleSaveDesign,
    handleSaveSettings,
    handleSaveLogic,
  ]);

  const handlePublish = useCallback(() => {
    const formData = new FormData();
    formData.set("intent", "publish");
    submit(formData, { method: "POST" });
  }, [submit]);

  const handleUnpublish = useCallback(() => {
    const formData = new FormData();
    formData.set("intent", "unpublish");
    submit(formData, { method: "POST" });
  }, [submit]);

  const handleDeleteConfirm = useCallback(() => {
    const formData = new FormData();
    formData.set("intent", "delete");
    submit(formData, { method: "POST" });
  }, [submit]);

  // ── Question handlers ──────────────────────────────────────────────────────

  const handleSelectQuestion = useCallback((index: number) => {
    setSelectedQuestionIndex(index);
  }, []);

  const handleUpdateField = useCallback(
    (
      field: keyof Question,
      value: string | boolean | QuestionSettings | QuestionLogic,
    ) => {
      setQuestions((prev) => {
        const updated = [...prev];
        updated[selectedQuestionIndex] = {
          ...updated[selectedQuestionIndex],
          [field]: value,
        };
        return updated;
      });
    },
    [selectedQuestionIndex],
  );

  const handleUpdateSettings = useCallback(
    (s: QuestionSettings) => {
      setQuestions((prev) => {
        const updated = [...prev];
        updated[selectedQuestionIndex] = {
          ...updated[selectedQuestionIndex],
          settings: s,
        };
        return updated;
      });
    },
    [selectedQuestionIndex],
  );

  const handleAddQuestion = useCallback(() => {
    const newQ = makeNewQuestion(questions.length);
    setQuestions((prev) => [...prev, newQ]);
    setSelectedQuestionIndex(questions.length);
  }, [questions.length]);

  const handleDeleteQuestion = useCallback(
    (index: number) => {
      setQuestions((prev) => prev.filter((_, i) => i !== index));
      setSelectedQuestionIndex((prev) =>
        prev >= index && prev > 0 ? prev - 1 : 0,
      );
    },
    [],
  );

  // ── Answer handlers ────────────────────────────────────────────────────────

  const handleUpdateAnswer = useCallback(
    (
      answerId: string,
      field: keyof AnswerOption,
      value: string | number | string[],
    ) => {
      setQuestions((prev) => {
        const updated = [...prev];
        const question = { ...updated[selectedQuestionIndex] };
        question.answers = question.answers.map((a) =>
          a.id === answerId ? { ...a, [field]: value } : a,
        );
        updated[selectedQuestionIndex] = question;
        return updated;
      });
    },
    [selectedQuestionIndex],
  );

  const handleAddAnswer = useCallback(() => {
    setQuestions((prev) => {
      const updated = [...prev];
      const question = { ...updated[selectedQuestionIndex] };
      question.answers = [
        ...question.answers,
        makeNewAnswer(question.answers.length, question.id),
      ];
      updated[selectedQuestionIndex] = question;
      return updated;
    });
  }, [selectedQuestionIndex]);

  const handleDeleteAnswer = useCallback(
    (answerId: string) => {
      setQuestions((prev) => {
        const updated = [...prev];
        const question = { ...updated[selectedQuestionIndex] };
        question.answers = question.answers.filter((a) => a.id !== answerId);
        updated[selectedQuestionIndex] = question;
        return updated;
      });
    },
    [selectedQuestionIndex],
  );

  const handleUpdateAnswerTags = useCallback(
    (answerId: string, tags: string[]) => {
      setQuestions((prev) => {
        const updated = [...prev];
        const question = { ...updated[selectedQuestionIndex] };
        question.answers = question.answers.map((a) =>
          a.id === answerId ? { ...a, productTags: tags } : a,
        );
        updated[selectedQuestionIndex] = question;
        return updated;
      });
    },
    [selectedQuestionIndex],
  );

  // ── Product mapping tag handlers ───────────────────────────────────────────

  const handleAddTag = useCallback(
    (questionId: string, answerId: string, tag: string) => {
      setQuestions((prev) =>
        prev.map((q) =>
          q.id === questionId
            ? {
                ...q,
                answers: q.answers.map((a) =>
                  a.id === answerId
                    ? { ...a, productTags: [...a.productTags, tag] }
                    : a,
                ),
              }
            : q,
        ),
      );
    },
    [],
  );

  const handleRemoveTag = useCallback(
    (questionId: string, answerId: string, tag: string) => {
      setQuestions((prev) =>
        prev.map((q) =>
          q.id === questionId
            ? {
                ...q,
                answers: q.answers.map((a) =>
                  a.id === answerId
                    ? {
                        ...a,
                        productTags: a.productTags.filter((t) => t !== tag),
                      }
                    : a,
                ),
              }
            : q,
        ),
      );
    },
    [],
  );

  // ── Logic handler ──────────────────────────────────────────────────────────

  const handleUpdateLogic = useCallback(
    (questionId: string, logic: QuestionLogic) => {
      setQuestions((prev) =>
        prev.map((q) => (q.id === questionId ? { ...q, logic } : q)),
      );
    },
    [],
  );

  // ── Status helpers ─────────────────────────────────────────────────────────

  const isLive = quiz.status === "active";
  const statusTone = isLive ? "success" : "attention";
  const statusLabel = isLive ? "Live" : "Draft";

  // ==========================================================================
  // RENDER
  // ==========================================================================

  return (
    <>
      <Page
        title={quizTitle || quiz.title}
        backAction={{
          content: "Quizzes",
          onAction: () => navigate("/app/quizzes"),
        }}
        titleMetadata={<Badge tone={statusTone}>{statusLabel}</Badge>}
        primaryAction={{
          content: "Save",
          icon: SaveIcon,
          onAction: handleSave,
        }}
        secondaryActions={[
          {
            content: "Preview",
            icon: EyeFirstIcon,
            onAction: () => navigate(`/app/quizzes/${quiz.id}/preview`),
          },
          isLive
            ? { content: "Unpublish", onAction: handleUnpublish }
            : { content: "Publish", onAction: handlePublish },
          {
            content: "Delete quiz",
            destructive: true,
            icon: DeleteIcon,
            onAction: () => setDeleteModalOpen(true),
          },
        ]}
      >
        <BlockStack gap="400">
          <Card padding="0">
            <Tabs
              tabs={tabs}
              selected={selectedTab}
              onSelect={setSelectedTab}
              fitted
            >
              <Box padding="400">
                {/* Tab 0 — Questions */}
                {selectedTab === 0 && (
                  <QuestionsTab
                    questions={questions}
                    selectedQuestionIndex={selectedQuestionIndex}
                    onSelectQuestion={handleSelectQuestion}
                    onUpdateField={handleUpdateField}
                    onUpdateSettings={handleUpdateSettings}
                    onUpdateAnswer={handleUpdateAnswer}
                    onAddAnswer={handleAddAnswer}
                    onDeleteAnswer={handleDeleteAnswer}
                    onUpdateAnswerTags={handleUpdateAnswerTags}
                    onAddQuestion={handleAddQuestion}
                    onDeleteQuestion={handleDeleteQuestion}
                  />
                )}

                {/* Tab 1 — Product Mapping */}
                {selectedTab === 1 && (
                  <ProductMappingTab
                    questions={questions}
                    onAddTag={handleAddTag}
                    onRemoveTag={handleRemoveTag}
                  />
                )}

                {/* Tab 2 — Design */}
                {selectedTab === 2 && (
                  <DesignTab
                    design={design}
                    quizTitle={quizTitle}
                    quizDescription={quizDescription}
                    onUpdateDesign={(field, value) =>
                      setDesign((prev) => ({ ...prev, [field]: value }))
                    }
                    onUpdateTitle={setQuizTitle}
                    onUpdateDescription={setQuizDescription}
                  />
                )}

                {/* Tab 3 — Settings */}
                {selectedTab === 3 && (
                  <SettingsTab
                    quiz={quiz}
                    quizTitle={quizTitle}
                    quizDescription={quizDescription}
                    quizSlug={quizSlug}
                    quizType={quizType}
                    settings={settings}
                    onUpdateTitle={setQuizTitle}
                    onUpdateDescription={setQuizDescription}
                    onUpdateSlug={setQuizSlug}
                    onUpdateType={setQuizType}
                    onUpdateSettings={setSettings}
                  />
                )}

                {/* Tab 4 — Logic */}
                {selectedTab === 4 && (
                  <LogicTab
                    questions={questions}
                    onUpdateLogic={handleUpdateLogic}
                  />
                )}
              </Box>
            </Tabs>
          </Card>
        </BlockStack>
      </Page>

      {/* Delete confirmation modal */}
      <Modal
        open={deleteModalOpen}
        onClose={() => setDeleteModalOpen(false)}
        title="Delete quiz?"
        primaryAction={{
          content: "Delete",
          destructive: true,
          onAction: handleDeleteConfirm,
        }}
        secondaryActions={[
          {
            content: "Cancel",
            onAction: () => setDeleteModalOpen(false),
          },
        ]}
      >
        <Modal.Section>
          <BlockStack gap="200">
            <Text as="p" variant="bodyMd">
              Are you sure you want to delete{" "}
              <strong>{quizTitle || quiz.title}</strong>?
            </Text>
            <Text as="p" variant="bodyMd" tone="subdued">
              This will permanently delete the quiz, all its questions, answers,
              and response data. This action cannot be undone.
            </Text>
          </BlockStack>
        </Modal.Section>
      </Modal>
    </>
  );
}

export const headers: HeadersFunction = (headersArgs) => {
  return boundary.headers(headersArgs);
};

