          </BlockStack>
        </InlineStack>
      </IndexTable.Cell>
      <IndexTable.Cell>
        <Badge tone={statusToneMap[quiz.status]}>
          {formatStatus(quiz.status)}
        </Badge>
      </IndexTable.Cell>
      <IndexTable.Cell>
        <Text as="span" variant="bodyMd" alignment="end">
          {quiz._count.questions}
        </Text>
      </IndexTable.Cell>
      <IndexTable.Cell>
        <Text as="span" variant="bodyMd" alignment="end">
          {quiz.completions.toLocaleString()}
        </Text>
      </IndexTable.Cell>
      <IndexTable.Cell>
        <Text as="span" variant="bodyMd" alignment="end">
          {"—"}
        </Text>
      </IndexTable.Cell>
      <IndexTable.Cell>
